        .filter(Boolean)
        .join(", ");
      console.log(
        `    ${relPath}: ${fileCounts} (${fileProseCached} cached, ${fileProseTranslated} translated)`,
      );
    }
  }

  return {
    glossaryTerms: totalGlossaryTerms,
    proseBlocks: totalProseBlocks,
    proseTranslated: totalProseTranslated,
    proseCached: totalProseCached,
