  expect(sidebarSummary).toContain("2 labels");
  expect(summary).toMatch(/\(\d+ cached, \d+ translated\)/);
  expect(process.exitCode).toBeUndefined();
  expect(writtenTo("docs.api.po")).toContain("pantoken-verbatim");
