  // `<name>` after it as bare prose Vue would parse as an unclosed element.
  expect(escapeBareHtmlTags("a ``width`/`height` b ``dist/<name>.png`` c `<img>` d")).toBe(
    "a ``width`/`height` b ``dist/&lt;name&gt;.png`` c `<img>` d",
  );
