  expect(cpSync).not.toHaveBeenCalled();
  expect(writeFileSync).not.toHaveBeenCalled();
  expect(logSpy.mock.calls.map((c: unknown[]) => String(c[0])).join("\n")).toContain(
    "skipping API locale build",
  );
});

