import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { escapePoString, parsePo } from "/Users/dwahl/Scripts/pantoken/tools/i18n-engine/src/po.ts";
import { PANTOKEN_VERBATIM_FLAG } from "/Users/dwahl/Scripts/pantoken/docs/scripts/refresh-api-pot.ts";

const root = "/Users/dwahl/Scripts/pantoken";
const catalogPaths = execFileSync("git", ["ls-files", "l10n/*/docs.api.po"], {
  cwd: root,
  encoding: "utf8",
})
  .trim()
  .split("\n");
const globalSources = new Set(
  parsePo(readFileSync(`${root}/l10n/docs.api.pot`, "utf8"))
    .filter((entry) => entry.flags.includes(PANTOKEN_VERBATIM_FLAG))
    .map((entry) => entry.msgid),
);
const localeSources = new Map([
  [
    ' ("Amira Patel"); ',
    ["ar", "ca", "da", "de", "el", "fi", "fr", "ga", "he", "hi", "ht", "hy", "id", "is", "it", "ja", "ko", "mi", "ms", "nl", "nn", "pt", "pt-BR", "se", "tr"],
  ],
  [
    ' ("Lee Harper"); ',
    ["ar", "ca", "da", "de", "el", "fi", "fr", "ga", "he", "hi", "ht", "hy", "id", "is", "it", "ja", "ko", "mi", "ms", "nl", "nn", "pt", "pt-BR", "se", "tr"],
  ],
  ["@alias Alias for `--value`.", ["nb"]],
  ["Action", ["fr", "fr-CA"]],
  ["Actions", ["fr", "fr-CA"]],
  ["Canvas:", ["ca", "da", "fi", "ht", "is", "it", "mi", "nb", "nl", "nn", "pt", "pt-BR", "se"]],
  ["Components", ["ca"]],
  ["Details", ["nl"]],
  ["Dr. Nguyen Van Thoc", ["ca"]],
  ["Miguel", ["ca"]],
  ["Miguel Sanchez", ["ca"]],
  ["OK", ["da", "nb"]],
  ["Orange", ["de", "fr", "fr-CA"]],
  ["Sanchez", ["ca"]],
  ["Score", ["nl"]],
]);
const localeForPath = (path) => path.split("/")[1];

function approveBlock(block, isGlobal) {
  const entry = parsePo(block)[0];
  if (
    !entry ||
    entry.obsolete ||
    entry.msgctxt !== "docs.api:prose" ||
    (!isGlobal &&
      entry.msgstr !== "" &&
      entry.msgstr.trim().toLowerCase() !== entry.msgid.trim().toLowerCase())
  )
    return block;

  const lines = block.split("\n");
  const flagsIndex = lines.findIndex((line) => line.startsWith("#,"));
  const flags = new Set(
    flagsIndex === -1
      ? []
      : lines[flagsIndex]
          .slice(2)
          .split(",")
          .map((flag) => flag.trim())
          .filter((flag) => flag !== "fuzzy"),
  );
  flags.add(PANTOKEN_VERBATIM_FLAG);
  const flagsLine = `#, ${[...flags].join(", ")}`;
  if (flagsIndex === -1) {
    const firstFieldIndex = lines.findIndex((line) => line.startsWith("msgctxt ") || line.startsWith("msgid "));
    lines.splice(firstFieldIndex, 0, flagsLine);
  } else {
    lines[flagsIndex] = flagsLine;
  }

  const msgstrIndex = lines.findIndex((line) => line.startsWith("msgstr "));
  if (msgstrIndex === -1) throw new Error(`Missing msgstr for ${entry.msgid}`);
  lines.splice(msgstrIndex, 1, `msgstr "${escapePoString(entry.msgid)}"`);
  while (lines[msgstrIndex + 1]?.startsWith('"')) lines.splice(msgstrIndex + 1, 1);
  return lines.join("\n");
}

for (const path of catalogPaths) {
  const locale = localeForPath(path);
  const source = execFileSync("git", ["show", `HEAD:${path}`], {
    cwd: root,
    encoding: "utf8",
    maxBuffer: 64 * 1024 * 1024,
  });
  const approvedSources = new Set(localeSources.get(locale) ?? []);
  const blocks = source.trimEnd().split(/\n\n+/u);
  const updated = blocks
    .map((block) => {
      const entry = parsePo(block)[0];
      if (!entry) return block;
      const isGlobal = globalSources.has(entry.msgid);
      return isGlobal || approvedSources.has(entry.msgid) ? approveBlock(block, isGlobal) : block;
    })
    .join("\n\n");
  const output = `${updated}\n`;
  if (output !== source) writeFileSync(`${root}/${path}`, output);
}

