const pot = parsePo(readFileSync(`${root}/l10n/docs.api.pot`, 'utf8'));
const globalSources = pot.filter((e) => e.flags.includes(PANTOKEN_VERBATIM_FLAG) && e.msgctxt === 'docs.api:prose');
const paths = execFileSync('git', ['ls-files', 'l10n/*/docs.api.po'], { encoding: 'utf8' }).trim().split('\n');
let checked = 0;
for (const path of paths) {
  const locale = path.split('/')[1];
  const entries = parsePo(readFileSync(`${root}/${path}`, 'utf8'));
  const bySource = new Map(entries.filter((e) => e.msgctxt === 'docs.api:prose').map((e) => [e.msgid, e]));
  for (const source of globalSources) {
    const entry = bySource.get(source.msgid);
    if (!entry || !entry.flags.includes(PANTOKEN_VERBATIM_FLAG) || entry.fuzzy || entry.msgstr !== source.msgid) {
      throw new Error(`${path}: global verbatim marker missing or incorrect for ${JSON.stringify(source.msgid)}`);
    }
    checked += 1;
  }
  for (const text of LOCALE_VERBATIM_API_PROSE.get(locale) ?? []) {
    const entry = bySource.get(text);
    if (entry && (entry.msgstr === '' || entry.msgstr.trim().toLowerCase() === entry.msgid.trim().toLowerCase()) && (!entry.flags.includes(PANTOKEN_VERBATIM_FLAG) || entry.fuzzy || entry.msgstr !== entry.msgid)) {
      throw new Error(`${path}: locale verbatim marker missing or incorrect for ${JSON.stringify(text)}`);
    }
  }
}
console.log(`Verified ${globalSources.length} global source markers across ${paths.length} catalogs (${checked} PO entries), plus locale-scoped passthroughs.`);
