arguments.command:
node --input-type=module <<'JS'
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { parsePo } from './tools/i18n-engine/src/po.ts';
import { LOCALE_VERBATIM_API_PROSE, PANTOKEN_VERBATIM_FLAG } from './docs/scripts/refresh-api-pot.ts';
const root = process.cwd();
const pot = parsePo(readFileSync(`${root}/l10n/docs.api.pot`, 'utf8'));
const globalSources = pot.filter((e) => !e.obsolete && e.flags.includes(PANTOKEN_VERBATIM_FLAG) && e.msgctxt === 'docs.api:prose');
const paths = execFileSync('git', ['ls-files', 'l10n/*/docs.api.po'], { encoding: 'utf8' }).trim().split('\n');
let checked = 0;
for (const path of paths) {
  const locale = path.split('/')[1];
  const entries = parsePo(readFileSync(`${root}/${path}`, 'utf8')).filter((e) => !e.obsolete && e.msgctxt === 'docs.api:prose');
  const bySource = new Map(entries.map((e) => [e.msgid, e]));
  for (const source of globalSources) {
    const entry = bySource.get(source.msgid);
    if (!entry) continue;
    if (!entry.flags.includes(PANTOKEN_VERBATIM_FLAG) || entry.fuzzy || entry.msgstr !== source.msgid) throw new Error(`${path}: global marker incorrect for ${JSON.stringify(source.msgid)}`);
    checked += 1;
  }
  for (const text of LOCALE_VERBATIM_API_PROSE.get(locale) ?? []) {
    const entry = bySource.get(text);
    if (entry && (entry.msgstr === '' || entry.msgstr.trim().toLowerCase() === entry.msgid.trim().toLowerCase()) && (!entry.flags.includes(PANTOKEN_VERBATIM_FLAG) || entry.fuzzy || entry.msgstr !== entry.msgid)) throw new Error(`${path}: locale marker incorrect for ${JSON.stringify(text)}`);
  }
}
console.log(`Verified ${globalSources.length} global source markers; ${checked} active PO entries across ${paths.length} catalogs, plus locale-scoped passthroughs.`);
JS

