arguments.command:
node --input-type=module <<'JS'
import { readFileSync } from 'node:fs';
import { parsePo } from './tools/i18n-engine/src/po.ts';
import { LOCALE_VERBATIM_API_PROSE, PANTOKEN_VERBATIM_FLAG } from './docs/scripts/refresh-api-pot.ts';
const log = readFileSync('/Users/dwahl/Downloads/job-logs.txt', 'utf8');
const pattern = /Z\s+! \[([^\]]+)\] cached prose translation for ("(?:[^"\\]|\\.)*") looks untranslated/g;
const globalSources = parsePo(readFileSync('l10n/docs.api.pot', 'utf8')).filter((e) => e.flags.includes(PANTOKEN_VERBATIM_FLAG)).map((e) => e.msgid);
const missed = new Set(); let diagnostics = 0;
for (const match of log.matchAll(pattern)) {
  diagnostics++;
  const locale = match[1];
  const text = JSON.parse(match[2]);
  const global = globalSources.some((source) => source === text || (text.length >= 30 && source.startsWith(text)));
  const local = (LOCALE_VERBATIM_API_PROSE.get(locale) ?? []).includes(text);
  if (!global && !local) missed.add(`${locale}: ${JSON.stringify(text)}`);
}
if (missed.size) throw new Error(`Uncovered diagnostics: ${[...missed].join('; ')}`);
console.log(`All ${diagnostics} diagnostic occurrences are covered by POT-global or locale-scoped verbatim markers.`);
JS

