arguments.command:
node --input-type=module <<'JS'
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { parsePo } from './tools/i18n-engine/src/po.ts';
import { LOCALE_VERBATIM_API_PROSE, PANTOKEN_VERBATIM_FLAG } from './docs/scripts/refresh-api-pot.ts';
const pot = parsePo(readFileSync('l10n/docs.api.pot', 'utf8'));
const globals = pot.filter((e) => !e.obsolete && e.flags.includes(PANTOKEN_VERBATIM_FLAG) && e.msgctxt === 'docs.api:prose');
const paths = execFileSync('git', ['ls-files', 'l10n/*/docs.api.po'], { encoding: 'utf8' }).trim().split('\n');
let globalChecked = 0, localeChecked = 0;
for (const path of paths) {
  const locale = path.split('/')[1];
  const active = parsePo(readFileSync(path, 'utf8')).filter((e) => !e.obsolete && e.msgctxt === 'docs.api:prose');
  const bySource = new Map(active.map((e) => [e.msgid, e]));
  for (const source of globals) {
    const e = bySource.get(source.msgid);
    if (!e) continue;
    if (!e.flags.includes(PANTOKEN_VERBATIM_FLAG) || e.fuzzy || e.msgstr !== e.msgid) throw new Error(`${path}: bad global marker ${JSON.stringify(source.msgid)}`);
    globalChecked++;
  }
  for (const text of LOCALE_VERBATIM_API_PROSE.get(locale) ?? []) {
    const e = bySource.get(text);
    if (e && (e.msgstr === '' || e.msgstr.trim().toLowerCase() === e.msgid.trim().toLowerCase())) {
      if (!e.flags.includes(PANTOKEN_VERBATIM_FLAG) || e.fuzzy || e.msgstr !== e.msgid) throw new Error(`${path}: bad locale marker ${JSON.stringify(text)}`);
      localeChecked++;
    }
  }
}
console.log(`Validated ${globalChecked} global and ${localeChecked} locale-specific active PO entries across ${paths.length} catalogs.`);
